selector_to_html = {"a[href=\"#diagramau-pentwr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.6. </span>Diagramau Pentwr<a class=\"headerlink\" href=\"#diagramau-pentwr\" title=\"Link to this heading\">#</a></h2><p>I gadw golwg ar ba newidynnau y gellir eu defnyddio lle, mae weithiau\u2019n ddefnyddiol\ntynnu <strong><a class=\"reference internal\" href=\"../glossary.html#term-diagram-pentwr\"><span class=\"xref std std-term\">diagram pentwr</span></a></strong>. Fel diagramau cyflwr, mae diagramau pentwr yn\ndangos gwerth pob newidyn, ond maent hefyd yn dangos pa swyddogaeth y mae pob\nnewidyn yn perthyn iddi.</p><p>Cynrychiolir pob swyddogaeth gan <strong><a class=\"reference internal\" href=\"../glossary.html#term-ffram\"><span class=\"xref std std-term\">ffram</span></a></strong>. Mae ffram yn flwch gydag enw\nswyddogaeth y tu allan a pharamedrau a newidynnau lleol y swyddogaeth y tu mewn.</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.11.4. </span>Ymarfer<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>Ysgrifennwch swyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">rectangle</span></code> sy\u2019n cymryd llinyn a dau gyfanrif ac\nyn tynnu petryal gyda\u2019r lled a\u2019r uchder penodol, wedi\u2019i wneud o gop\u00efau o\u2019r llinyn.\nDyma enghraifft o betryal gyda lled <code class=\"docutils literal notranslate\"><span class=\"pre\">5</span></code> ac uchder <code class=\"docutils literal notranslate\"><span class=\"pre\">4</span></code>, wedi\u2019i wneud o\u2019r llinyn\n<code class=\"docutils literal notranslate\"><span class=\"pre\">'H'</span></code>.</p>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.11.5. </span>Ymarfer<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p>Mae\u2019r g\u00e2n \u201c99 Bottles of Beer\u201d yn dechrau gyda\u2019r pennill hwn:</p>", "a[href=\"#ymarferion\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.11. </span>Ymarferion<a class=\"headerlink\" href=\"#ymarferion\" title=\"Link to this heading\">#</a></h2><h3><span class=\"section-number\">3.11.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Mae\u2019r gosodiadau mewn swyddogaeth neu ddolen <code class=\"docutils literal notranslate\"><span class=\"pre\">for</span></code> wedi\u2019u mewnoli \u00e2 phedwar\nbwlch, yn \u00f4l confensiwn. Ond nid yw pawb yn cytuno \u00e2\u2019r confensiwn hwnnw. Os ydych\nyn chwilfrydig am hanes y ddadl fawr hon, gofynnwch i gynorthwyydd rhithwir i\n\u201cdweud wrthyf am fylchau a thabiau yn Python\u201d.</p><p>Mae cynorthwywyr rhithwir yn eithaf da am ysgrifennu swyddogaethau bach.</p>", "a[href=\"#hanes-galwadau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.7. </span>Hanes Galwadau<a class=\"headerlink\" href=\"#hanes-galwadau\" title=\"Link to this heading\">#</a></h2><p>Pan fydd gwall rhedeg yn digwydd mewn swyddogaeth, mae Python yn dangos enw\u2019r\nswyddogaeth oedd yn rhedeg, enw\u2019r swyddogaeth a\u2019i galwodd, ac yn y blaen, i fyny\u2019r\npentwr. I ddangos enghraifft, byddaf yn diffinio fersiwn o <code class=\"docutils literal notranslate\"><span class=\"pre\">print_twice</span></code> sy\u2019n\ncynnwys gwall \u2014 mae\u2019n ceisio argraffu <code class=\"docutils literal notranslate\"><span class=\"pre\">cat</span></code>, sy\u2019n newidyn lleol mewn swyddogaeth\narall.</p>", "a[href=\"../glossary.html#term-diffiniad-swyddogaeth\"]": "<dt id=\"term-diffiniad-swyddogaeth\">diffiniad swyddogaeth</dt><dd><p>function definition</p></dd>", "a[href=\"../glossary.html#term-paramedr\"]": "<dt id=\"term-paramedr\">paramedr</dt><dd><p>parameter</p></dd>", "a[href=\"#galw-swyddogaethau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.3. </span>Galw swyddogaethau<a class=\"headerlink\" href=\"#galw-swyddogaethau\" title=\"Link to this heading\">#</a></h2><p>Unwaith y byddwch wedi diffinio swyddogaeth, gallwch ei defnyddio y tu mewn i\nswyddogaeth arall. I ddangos hyn, byddwn yn ysgrifennu swyddogaethau sy\u2019n argraffu\ngeiriau \u201cThe Spam Song\u201d\n(<a class=\"reference external\" href=\"https://www.songfacts.com/lyrics/monty-python/the-spam-song\">https://www.songfacts.com/lyrics/monty-python/the-spam-song</a>).</p>", "a[href=\"../glossary.html#term-corff\"]": "<dt id=\"term-corff\">corff</dt><dd><p>body</p></dd>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.11.3. </span>Ymarfer<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>Ysgrifennwch swyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">triangle</span></code> sy\u2019n cymryd llinyn a chyfanrif ac yn\ntynnu pyramid gyda\u2019r uchder penodol, wedi\u2019i wneud o gop\u00efau o\u2019r llinyn. Dyma\nenghraifft o byramid gyda <code class=\"docutils literal notranslate\"><span class=\"pre\">5</span></code> lefel, gan ddefnyddio\u2019r llinyn <code class=\"docutils literal notranslate\"><span class=\"pre\">'L'</span></code>.</p>", "a[href=\"#pam-swyddogaethau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.8. </span>Pam Swyddogaethau?<a class=\"headerlink\" href=\"#pam-swyddogaethau\" title=\"Link to this heading\">#</a></h2><p>Efallai nad yw\u2019n glir eto pam mae\u2019n werth y drafferth i rannu rhaglen yn\nswyddogaethau. Mae sawl rheswm:</p>", "a[href=\"#mae-newidynnau-a-pharamedrau-n-lleol\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.5. </span>Mae Newidynnau a Pharamedrau\u2019n Lleol<a class=\"headerlink\" href=\"#mae-newidynnau-a-pharamedrau-n-lleol\" title=\"Link to this heading\">#</a></h2><p>Pan fyddwch yn creu newidyn y tu mewn i swyddogaeth, mae\u2019n <strong><a class=\"reference internal\" href=\"../glossary.html#term-newidyn-lleol\"><span class=\"xref std std-term\">newidyn lleol</span></a></strong>,\nsy\u2019n golygu ei fod ond yn bodoli y tu mewn i\u2019r swyddogaeth. Er enghraifft, mae\u2019r\nswyddogaeth ganlynol yn cymryd dwy ddadl, yn eu cydgatenu, ac yn argraffu\u2019r\ncanlyniad ddwywaith.</p>", "a[href=\"../glossary.html#term-hanes-galwadau\"]": "<dt id=\"term-hanes-galwadau\">hanes galwadau</dt><dd><p>traceback</p></dd>", "a[href=\"#diffinio-swyddogaethau-newydd\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.1. </span>Diffinio swyddogaethau newydd<a class=\"headerlink\" href=\"#diffinio-swyddogaethau-newydd\" title=\"Link to this heading\">#</a></h2><p>Mae <strong><a class=\"reference internal\" href=\"../glossary.html#term-diffiniad-swyddogaeth\"><span class=\"xref std std-term\">diffiniad swyddogaeth</span></a></strong> yn nodi enw swyddogaeth newydd a\u2019r dilyniant\no osodiadau sy\u2019n rhedeg pan gaiff y swyddogaeth ei galw. Dyma enghraifft:</p>", "a[href=\"../glossary.html#term-diagram-pentwr\"]": "<dt id=\"term-diagram-pentwr\">diagram pentwr</dt><dd><p>stack diagram</p></dd>", "a[href=\"../glossary.html#term-ffram\"]": "<dt id=\"term-ffram\">ffram</dt><dd><p>frame</p></dd>", "a[href=\"#ailadrodd\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.4. </span>Ailadrodd<a class=\"headerlink\" href=\"#ailadrodd\" title=\"Link to this heading\">#</a></h2><p>Os ydym am ddangos mwy nag un pennill, gallwn ddefnyddio gosodiad <code class=\"docutils literal notranslate\"><span class=\"pre\">for</span></code>. Dyma\nenghraifft syml.</p>", "a[href=\"../glossary.html#term-newidyn-lleol\"]": "<dt id=\"term-newidyn-lleol\">newidyn lleol</dt><dd><p>local variable</p></dd>", "a[href=\"#swyddogaethau\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3. </span>Swyddogaethau<a class=\"headerlink\" href=\"#swyddogaethau\" title=\"Link to this heading\">#</a></h1><p>Yn y bennod flaenorol fe wnaethom ddefnyddio sawl swyddogaeth a ddarperir gan\nPython, fel <code class=\"docutils literal notranslate\"><span class=\"pre\">int</span></code> a <code class=\"docutils literal notranslate\"><span class=\"pre\">float</span></code>, a rhai a ddarperir gan y modiwl <code class=\"docutils literal notranslate\"><span class=\"pre\">math</span></code>, fel <code class=\"docutils literal notranslate\"><span class=\"pre\">sqrt</span></code> a\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pow</span></code>.</p><p>Yn y bennod hon, byddwch yn dysgu sut i greu eich swyddogaethau eich hun a\u2019u\nrhedeg. A byddwn yn gweld sut gall un swyddogaeth alw un arall. Fel enghreifftiau,\nbyddwn yn dangos geiriau caneuon gan Monty Python. Mae\u2019r enghreifftiau ff\u00f4l hyn yn\ndangos nodwedd bwysig \u2014 mae\u2019r gallu i ysgrifennu eich swyddogaethau eich hun yn\nsylfaen rhaglennu.</p>", "a[href=\"#gofyn-i-gynorthwyydd-rhithwir\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.11.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Mae\u2019r gosodiadau mewn swyddogaeth neu ddolen <code class=\"docutils literal notranslate\"><span class=\"pre\">for</span></code> wedi\u2019u mewnoli \u00e2 phedwar\nbwlch, yn \u00f4l confensiwn. Ond nid yw pawb yn cytuno \u00e2\u2019r confensiwn hwnnw. Os ydych\nyn chwilfrydig am hanes y ddadl fawr hon, gofynnwch i gynorthwyydd rhithwir i\n\u201cdweud wrthyf am fylchau a thabiau yn Python\u201d.</p><p>Mae cynorthwywyr rhithwir yn eithaf da am ysgrifennu swyddogaethau bach.</p>", "a[href=\"#dadnamu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.9. </span>Dadnamu<a class=\"headerlink\" href=\"#dadnamu\" title=\"Link to this heading\">#</a></h2><p>Gall dadnamu fod yn rhwystredig, ond mae hefyd yn heriol, yn ddiddorol, ac weithiau\nhyd yn oed yn hwyl. Ac mae\u2019n un o\u2019r sgiliau pwysicaf y gallwch eu dysgu.</p><p>Mewn rhai ffyrdd mae dadnamu fel gwaith ditectif. Rhoddir cliwiau i chi ac mae\u2019n\nrhaid i chi ddidynnu\u2019r digwyddiadau a arweiniodd at y canlyniadau rydych yn eu\ngweld.</p>", "a[href=\"#paramedrau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.2. </span>Paramedrau<a class=\"headerlink\" href=\"#paramedrau\" title=\"Link to this heading\">#</a></h2><p>Mae rhai o\u2019r swyddogaethau rydym wedi\u2019u gweld yn gofyn am ddadleuon; er enghraifft,\npan alwch <code class=\"docutils literal notranslate\"><span class=\"pre\">abs</span></code> rydych yn pasio rhif fel dadl. Mae rhai swyddogaethau\u2019n cymryd mwy\nnag un ddadl; er enghraifft, mae <code class=\"docutils literal notranslate\"><span class=\"pre\">math.pow</span></code> yn cymryd dwy, y sail a\u2019r esbonydd.</p><p>Dyma ddiffiniad ar gyfer swyddogaeth sy\u2019n cymryd dadl.</p>", "a[href=\"#rhestr-termau-r-bennod\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.10. </span>Rhestr Termau\u2019r Bennod<a class=\"headerlink\" href=\"#rhestr-termau-r-bennod\" title=\"Link to this heading\">#</a></h2><p><strong>diffiniad swyddogaeth:</strong>\nGosodiad sy\u2019n creu swyddogaeth.</p><p><strong>pennawd:</strong>\nLlinell gyntaf diffiniad swyddogaeth.</p>", "a[href=\"../glossary.html#term-dolen\"]": "<dt id=\"term-dolen\">dolen</dt><dd><p>loop</p></dd>", "a[href=\"#ymarfer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">3.11.2. </span>Ymarfer<a class=\"headerlink\" href=\"#ymarfer\" title=\"Link to this heading\">#</a></h3><p>Ysgrifennwch swyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">print_right</span></code> sy\u2019n cymryd llinyn o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">text</span></code>\nfel paramedr ac yn argraffu\u2019r llinyn gyda digon o fylchau blaenorol fel bod\nllythyren olaf y llinyn yn y 40fed golofn o\u2019r arddangosfa.</p>", "a[href=\"../glossary.html#term-gwrthrych-swyddogaeth\"]": "<dt id=\"term-gwrthrych-swyddogaeth\">gwrthrych swyddogaeth</dt><dd><p>function object</p></dd>", "a[href=\"../glossary.html#term-pennawd\"]": "<dt id=\"term-pennawd\">pennawd</dt><dd><p>header</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
